"""Server-rendered accessible interface; every dynamic value is escaped."""
import html,json
from loan_core import DEMO_CASES

def e(x):return html.escape(str(x),quote=True)
def pct(x):return f'{x:.1%}'
def money(x):return 'INR '+f'{x:,.0f}'

def layout(title,content,ctx):
    nav=''.join(f'<a href="{url}" {"aria-current=page" if ctx.get("page")==url else ""}>{label}</a>' for url,label in [('/','New application'),('/policy','Lending policy'),('/evaluation','Model evaluation'),('/about','How it works'),('/review','Officer review')])
    state='OpenRouter connected' if ctx['llm'] else 'LLM not connected'
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} · Team 12</title><link rel="stylesheet" href="/style.css"></head><body><div class="shell"><aside><a class="brand" href="/"><span class="mark">C</span>Cedar Demo Bank</a><p class="team">SECTION C / TEAM 12</p><nav>{nav}</nav><div class="side-note"><b>Classroom prototype</b><p>Fictional lending policy and synthetic applicants. Not financial advice.</p></div></aside><main><header><div><p class="eyebrow">LOAN DECISION AND EXPLANATION SYSTEM</p><h1>{e(title)}</h1></div><span class="status">{state}</span></header>{content}<footer>Educational demonstration · Synthetic cases are stored locally for review · No funds are released</footer></main></div></body></html>'''

def notice(text):return f'<div class="notice" role="status">{e(text)}</div>'
def csrf(ctx):return f'<input type="hidden" name="csrf" value="{e(ctx["csrf"])}">'

def home(ctx,values=None,cases=(),error=''):
    x=values or DEMO_CASES['approval']
    specs=[('income','Annual gross income','INR',120000,5000000,1),('monthly_debt','Existing monthly debt payments','INR',0,200000,1),('loan_amount','Requested loan amount','INR',10000,2000000,1),('term_months','Repayment term','months',6,84,1),('credit_score','Credit score','300–900',300,900,1),('late_payments','Late payments in last 12 months','count',0,12,1),('employment_years','Employment experience','years',0,40,.1)]
    fields=''.join(f'<label for="{k}">{label}<span>{unit}</span><input id="{k}" name="{k}" type="number" min="{lo}" max="{hi}" step="{step}" required value="{e(x[k])}"></label>' for k,label,unit,lo,hi,step in specs)
    options=''.join(f'<option value="{value}" {"selected" if value==x["employment_type"] else ""}>{label}</option>' for value,label in [('salaried','Salaried'),('self_employed','Self-employed — outside policy scope')])
    fields+=f'<label for="employment_type">Employment type<span>Product coverage</span><select name="employment_type" id="employment_type">{options}</select></label>'
    samples=''.join(f'<a class="sample" href="/?case={name}"><b>{label}</b><span>{desc}</span></a>' for name,label,desc in [('approval','01 / Approval','Strong repayment profile'),('rejection','02 / Rejection','Debt and repayment concerns'),('edge','03 / Policy gap','Self-employed income')])
    history=''.join(f'<li><a href="/case?id={c["id"]}">Case {c["id"][:8]}</a><span>{e(c["status"])}</span></li>' for c in cases[:5])
    content=(notice(error) if error else '')+f'''<p class="lead">Enter a synthetic applicant. See the model recommendation, the exact policy evidence and a separate officer decision.</p><div class="samples">{samples}</div><div class="columns"><section class="card"><h2>Financial details</h2><form action="/apply" method="post">{csrf(ctx)}<div class="fields">{fields}</div><label class="check"><input type="checkbox" name="use_llm" value="yes">Generate an explanation with OpenRouter using these synthetic details and the retrieved policy.</label><p class="muted">The model runs locally. This checkbox sends the financial values to OpenRouter and its provider; no identity details are collected.</p><button type="submit">Assess application <span>→</span></button></form></section><div><section class="card accent"><p class="eyebrow">THE REVIEW PROCESS</p><ol class="steps"><li><b>Predict</b><span>Estimate repayment using the trained model.</span></li><li><b>Retrieve</b><span>Search the policy and include every triggered clause.</span></li><li><b>Explain</b><span>The LLM drafts reasons with exact source quotations.</span></li><li><b>Review</b><span>An officer signs off with a recorded reason.</span></li></ol></section><section class="card"><h2>Your recent cases</h2><ul class="history">{history or '<li>No cases submitted yet.</li>'}</ul></section></div></div>'''
    return layout('Assess a loan application',content,ctx)

def case_page(ctx,case,error=''):
    a=case['assessment'];g=case['generation'];x=a['input'];isapprove=a['recommendation']=='Approve'
    flags=''.join(f'<li><a href="/policy#{e(f["clause"])}">{e(f["clause"])}</a> {e(f["message"])}</li>' for f in a['flags']) or '<li>No numeric policy review trigger. Officer review is still required.</li>'
    sources=''.join(f'<article class="source"><div><a href="/policy#{c["id"]}">{e(c["id"])}</a> <b>{e(c["title"])}</b></div><p>{e(c["text"])}</p><small>{e(c["reason"])} · relevance {c["score"]:.3f}</small></article>' for c in a['evidence'])
    if g['status']=='generated':
        draft=g['draft'];reasons=''.join(f'<article class="reason"><h3>{e(r["clause_id"])}</h3><blockquote>{e(r["policy_quote"])}</blockquote><p>{e(r["explanation"])}</p></article>' for r in draft['reasons'])
        explanation=f'<span class="pill good">LLM generated</span><p class="summary">{e(draft["summary"])}</p>{reasons}<p class="muted">Served by {e(g["resolved_model"])}. Quotations were checked against the retrieved source; factual meaning still needs human review.</p>'
    else:explanation=f'<span class="pill">No LLM explanation</span><p>{e(g["message"])}</p><p class="muted">The recommendation and policy evidence below are available. No template is presented as AI-generated text.</p>'
    factors=''.join(f'<li><b>{e(c["feature"])}</b><span>{"Raises" if c["contribution"]>=0 else "Lowers"} model log-odds by {abs(c["contribution"]):.2f}</span></li>' for c in a['contributions'][:3])
    details=''.join(f'<div><dt>{e(k.replace("_"," ").title())}</dt><dd>{e(v)}</dd></div>' for k,v in x.items())
    review=''
    if case['reviews']:
        r=case['reviews'][-1];review=f'<h2>Recorded officer decision</h2><p><span class="pill">{e(r["decision"])}</span></p><p>{e(r["note"])}</p><small>Audit time {e(r["created"])} · Exception acknowledged: {"yes" if r["exception"] else "no"}</small>'
    elif ctx.get('reviewer'):
        review=f'''<h2>Officer sign-off</h2><p>Review the input values, model associations, exact source quotations and policy exceptions.</p><form method="post" action="/signoff">{csrf(ctx)}<input type="hidden" name="case_id" value="{e(case['id'])}"><label>Decision<select name="decision"><option>More information required</option><option>Rejected</option><option>Approved</option></select></label><label>Reason for the decision<textarea name="note" required minlength="20" maxlength="2000" rows="3" placeholder="Explain the policy basis, any override and what the applicant needs to do."></textarea></label><label class="check"><input type="checkbox" name="reviewed" value="yes" required>I reviewed the inputs, policy evidence and any explanation.</label><label class="check"><input type="checkbox" name="exception" value="yes">I explicitly approve a documented policy exception, if applicable.</label><button>Record officer decision</button></form>'''
    else:review='<h2>Human checkpoint</h2><p>This case is held for a loan officer. A model recommendation does not become a final decision automatically.</p><a class="button secondary" href="/review">Open officer review</a>'
    content=(notice(error) if error else '')+f'''<p class="lead">Case {e(case['id'][:8])} · Policy v{e(a['policy_version'])} · {e(case['status'])}</p><div class="metrics"><div><small>Model recommendation</small><strong class="{"green" if isapprove else "red"}">{e(a['recommendation'])}</strong></div><div><small>Synthetic repayment score</small><strong>{pct(a['probability'])}</strong></div><div><small>Decision threshold</small><strong>{pct(a['threshold'])}</strong></div><div><small>Total debt service</small><strong>{pct(a['derived']['total_dti'])}</strong></div></div><div class="columns"><div><section class="card"><h2>Policy review flags</h2><ul class="flags">{flags}</ul><p class="muted">Estimated proposed payment: {money(a['derived']['proposed_payment'])}/month at the policy's illustrative 12% annual rate.</p></section><section class="card"><h2>Policy-grounded explanation</h2>{explanation}</section><section class="card">{review}</section></div><div><section class="card"><h2>Model associations</h2><ul class="history">{factors}</ul><p class="muted">Compared with the training average. These are model associations, not proven causes or real-world creditworthiness.</p></section><section class="card"><h2>Submitted values</h2><dl>{details}</dl></section></div></div><section class="card"><h2>RAG evidence trail</h2><p>The search ranked the policy text with BM25. Exact rule matches and review obligations were added so relevant clauses cannot be lost through ranking.</p><details><summary>View retrieval query and policy fingerprint</summary><p>{e(a['retrieval_query'])}</p><code>{e(a['policy_fingerprint'])}</code></details><div class="evidence">{sources}</div></section>'''
    return layout('Application assessment',content,ctx)

def policy_page(ctx,policy):
    content=f'<p class="lead">{e(policy.data["name"])} · Version {e(policy.version)} · Fictional policy written for this project.</p>'
    content+=notice('The source is policy.json. Its text is searched by RAG; its structured limits drive exact policy checks. No customer or bank confidential documents are needed.')
    content+=''.join(f'<section class="card" id="{c["id"]}"><p class="eyebrow">{c["id"]}</p><h2>{e(c["title"])}</h2><p>{e(c["text"])}</p></section>' for c in policy.clauses)
    return layout('The lending policy',content,ctx)

def evaluation(ctx,model):
    rows=''
    for name,m in [(f"Model at {model['threshold']:.2f}",model['test_metrics']),('Model at 0.50 (comparison only)',model['test_at_050']),('Majority baseline: reject all',model['baseline_metrics'])]:
        rows+=f'<tr><th>{e(name)}</th><td>{pct(m["accuracy"])}</td><td>{pct(m["precision"])}</td><td>{pct(m["recall"])}</td><td>{m["fp"]}</td><td>{m["fn"]}</td><td>{m["error_cost_units"]}</td></tr>'
    m=model['test_metrics']
    content=f'''<p class="lead">A reproducible, held-out evaluation on simulated repayment outcomes.</p>{notice('These figures are from synthetic data. They are not evidence that the model is safe, accurate or fair on real loan applicants.')}<section class="card"><h2>Training and evaluation design</h2><div class="metrics"><div><small>Training records</small><strong>1,440</strong></div><div><small>Validation records</small><strong>480</strong></div><div><small>Held-out test records</small><strong>480</strong></div></div><p>Logistic regression learns from five financial features. The validation set selects the threshold using an assumed cost of 5 units for approving a simulated non-repayer and 1 unit for missing a simulated repayer. The test set is used only for reporting.</p><div class="table-scroll"><table><thead><tr><th>Method</th><th>Accuracy</th><th>Approval precision</th><th>Approval recall</th><th>False approvals</th><th>Missed approvals</th><th>Error cost units</th></tr></thead><tbody>{rows}</tbody></table></div><p class="muted">Precision uses successful repayment as positive. Baseline precision is reported as 0 when there are no approvals. Threshold 0.50 is a fixed reference, not a second selection on test data.</p></section><div class="columns"><section class="card"><h2>Confusion matrix</h2><table><tr><th></th><th>Repaid</th><th>Did not repay</th></tr><tr><th>Model approves</th><td>{m['tp']}</td><td>{m['fp']}</td></tr><tr><th>Model rejects</th><td>{m['fn']}</td><td>{m['tn']}</td></tr></table><p>The conservative threshold reduces false approvals but misses many simulated repayers. This trade-off affects customer access and requires business review.</p></section><section class="card"><h2>LLM evaluation</h2><p>Live explanation accuracy has not been measured in this package. Run <code>python3 evaluate_llm.py</code> after configuring a key. It saves 30 drafts and a rubric for human review.</p><p>Track wrong facts, wrong policy interpretation, missing clauses, decision changes, refusals and latency. Exact quotation checks do not measure hallucination by themselves.</p></section></div><section class="card"><h2>Known limitations</h2><ul>{''.join('<li>'+e(s)+'</li>' for s in model['limitations'])}</ul></section>'''
    return layout('Model evaluation',content,ctx)

def review_page(ctx,cases,error=''):
    if not ctx.get('reviewer'):
        content=notice(error) if error else ''
        content+=f'<section class="card narrow"><h2>Demo officer access</h2><p>Enter reviewer mode to check the synthetic applications and record a demo decision. No password is required.</p><form action="/login" method="post">{csrf(ctx)}<button>Open review queue</button></form></section>'
    else:
        rows=''.join(f'<tr><td><a href="/case?id={c["id"]}">{e(c["id"][:8])}</a></td><td>{e(c["created"])}</td><td>{e(c["status"])}</td><td><a href="/case?id={c["id"]}">Review case →</a></td></tr>' for c in cases)
        content=f'<section class="card"><h2>Review queue</h2><p>Only an authenticated demo officer can record a final decision. Each sign-off records its reason and time.</p><table><thead><tr><th>Case</th><th>Created (UTC)</th><th>Status</th><th>Action</th></tr></thead><tbody>{rows or "<tr><td colspan=4>No applications yet.</td></tr>"}</tbody></table><form action="/logout" method="post">{csrf(ctx)}<button class="secondary">Sign out of officer review</button></form></section>'
    return layout('Officer review',content,ctx)

def about(ctx):
    return layout('How the system works','''<p class="lead">Five separate steps make the recommendation explainable and reviewable.</p><section class="card"><ol class="steps horizontal"><li><b>1. Applicant</b><span>Financial inputs validated</span></li><li><b>2. Model</b><span>Repayment score and recommendation</span></li><li><b>3. Retrieval</b><span>Relevant clauses from our policy</span></li><li><b>4. LLM</b><span>Explanation plus exact quotations</span></li><li><b>5. Officer</b><span>Decision and audit reason</span></li></ol></section><div class="columns"><section class="card"><h2>What RAG retrieves</h2><p>The knowledge base is the fictional Cedar Demo Bank policy. Each numbered clause is a document chunk. BM25 searches these chunks using the case facts and policy flags. Triggered clauses and human-review obligations are always included.</p><p>The LLM receives only the retrieved evidence and case facts. Its cited quotes must match the source text. The answer stays a draft until a human reviews it.</p></section><section class="card"><h2>Why use RAG</h2><p>A general LLM does not know this bank's private rules. Retrieval supplies the relevant version of the policy and supports citations the reviewer can inspect. Changing the policy updates the evidence without retraining the language model.</p><p>RAG does not guarantee a correct interpretation. We still validate quotations and require human factual review.</p></section></div><section class="card"><h2>What the two models do</h2><p>The local logistic regression predicts simulated repayment. The hosted LLM explains that model recommendation using policy evidence. If the LLM is disconnected or its output fails validation, the app shows that state explicitly and does not manufacture an explanation.</p></section>''',ctx)
